57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
67	     * memberId and registrationDate. */
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    /** Dedicated notification logger: on a successful create a welcome notification is enqueued,
71	     * recording the owner id and memberId. */
72	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
73	
74	    /** Serializes the structured {@link OwnerCreatedEvent} emitted on each create. */
75	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
76	
77	    /** Monotonically increasing sequence number assigned to each successful create's audit event. */
78	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong();
79	
80	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
81	    private static final int CITY_CAPACITY = 50;
82	
83	    /** Once a city already holds at least this many owners (but fewer than {@link #CITY_CAPACITY}),
84	     * a new owner created for that city is flagged with {@code capacityWarning} to signal the city
85	     * is approaching its capacity limit. */
86	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
87	
88	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
89	     * create is rejected once this many owners already carry today's registration date. */
90	    private static final int DAILY_REGISTRATION_LIMIT = 100;
91	
92	    /** Once more than this many owners already carry a given day's registration date, a new owner
93	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
94	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
95	
96	    /** HTTP header carrying the client-supplied idempotency key for a create. */
97	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
98	
99	    private final ClinicService clinicService;
100	
101	    private final OwnerMapper ownerMapper;
102	
103	    private final PetMapper petMapper;
104	
105	    private final VisitMapper visitMapper;
106	
107	    private final HttpServletRequest request;
108	
109	    private final IdempotencyStore idempotencyStore;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 HttpServletRequest request,
116	                                 IdempotencyStore idempotencyStore) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	        this.request = request;
122	        this.idempotencyStore = idempotencyStore;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
153	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
154	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
155	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
156	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
157	        if (hasIdempotencyKey) {
158	            Optional<Owner> existing = this.idempotencyStore.find(idempotencyKey)
159	                .map(this.clinicService::findOwnerById);
160	            if (existing.isPresent()) {
161	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing.get()), HttpStatus.OK);
162	            }
163	        }
164	        HttpHeaders headers = new HttpHeaders();
165	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
166	        // The effective registration date (supplied, or the server date when omitted) must fall on
167	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
168	        // registration date — the stored value, the per-day limit below and the membership number —
169	        // uses this adjusted date.
170	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
171	        owner.setRegistrationDate(effectiveDate);
172	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
173	        // further creates for that day with 429 Too Many Requests.
174	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
175	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
176	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
177	        }
178	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
179	        // for its registration date, signalling a bulk-signup surge.
180	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
181	        // Per-city capacity: a city that already holds the maximum number of owners is full.
182	        int ownersInCity = this.clinicService.countOwnersInCity(owner.getCity());
183	        if (ownersInCity >= CITY_CAPACITY) {
184	            return new ResponseEntity<>(HttpStatus.CONFLICT);
185	        }
186	        // Capacity warning: flag this owner when its city already holds between the warning
187	        // threshold (40) and the hard limit (49), signalling the city is approaching capacity.
188	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
189	        // The household id is derived deterministically on the owner itself (see
190	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
191	        // last name and postcode share it automatically — no linking step and no ordering to manage.
192	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
193	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
194	        // (the SHA-256 of normalized telephone | lower-cased email-or-empty | soundex(lastName))
195	        // equals an existing owner's. A truly identical record is always rejected, independent of
196	        // sharesHousehold.
197	        if (this.clinicService.isIdentityKeyInUse(owner)) {
198	            return new ResponseEntity<>(HttpStatus.CONFLICT);
199	        }
200	        // Household membership: another owner may already belong to this (last name, postcode)
201	        // household. A new member is admitted rather than rejected — its membership level is instead
202	        // capped relative to the household (see below). An undeclared member (sharesHousehold not
203	        // set) that is not an exact-identity duplicate is still allowed through, flagged as a
204	        // possible duplicate for review.
205	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
206	        // Soft "possible duplicate" detection: an existing owner's last name has the same Soundex
207	        // code and the same postcode, while its identity key differs (so it is not a hard
208	        // duplicate). A declared household member (sharesHousehold on an in-use household) is an
209	        // intentional share, not a suspected duplicate, so it is not flagged; otherwise the create
210	        // still proceeds, flagged with possibleDuplicate=true and possibleDuplicateOf set to the
211	        // matching owner id.
212	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
213	            ? null
214	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
215	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
216	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
217	        owner.setNamesakeCount(
218	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
219	        // Membership-level ceiling: a new owner's membershipLevel may not exceed one above the
220	        // current maximum level among its existing household members. Derive the cap from those
221	        // members' effective (already-capped) levels; with no existing member the cap stays null
222	        // and the owner's level is used uncapped.
223	        Collection<Owner> householdMembers = this.clinicService.findHouseholdMembers(owner);
224	        if (!householdMembers.isEmpty()) {
225	            int maxHouseholdLevel = householdMembers.stream()
226	                .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
227	                .max()
228	                .getAsInt();
229	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
230	        }
231	        this.clinicService.saveOwner(owner);
232	        // Compute the derived membership level once so the human-readable line and the structured
233	        // event below are guaranteed to report the identical value.
234	        int membershipLevel = ownerMapper.formatMembershipLevel(owner);
235	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
236	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
237	        // In addition to the human-readable audit line above, emit an immutable structured event.
238	        // The event carries the owner's current primary identifier (the memberId) via
239	        // Owner.getPrimaryIdentifier(), and a sequence number that strictly increases across creates.
240	        OwnerCreatedEvent event = new OwnerCreatedEvent(
241	            AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(), owner.getPrimaryIdentifier(),
242	            membershipLevel, OwnerCreatedEvent.EVENT_TYPE);
243	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
244	        // Enqueue a welcome notification for the newly created owner, recording the owner id and
245	        // memberId so the notification pipeline can address the member.
246	        NOTIFY.info("welcome notification enqueued for owner id={} memberId={}",
247	            owner.getId(), owner.getMemberId());
248	        if (hasIdempotencyKey) {
249	            this.idempotencyStore.record(idempotencyKey, owner.getId());
250	        }
251	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
252	        headers.setLocation(UriComponentsBuilder.newInstance()
253	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
254	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
260	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
261	        if (currentOwner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
265	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
266	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
267	        currentOwner.setCity(ownerFieldsDto.getCity());
268	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
269	        currentOwner.setLastName(ownerFieldsDto.getLastName());
270	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
271	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
272	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
273	        this.clinicService.saveOwner(currentOwner);
274	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Transactional
279	    @Override
280	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
281	        Owner owner = this.clinicService.findOwnerById(ownerId);
282	        if (owner == null) {
283	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	        }
285	        this.clinicService.deleteOwner(owner);
286	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
287	    }
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
292	        Owner owner = this.clinicService.findOwnerById(ownerId);
293	        if (owner == null) {
294	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	        }
296	        HttpHeaders headers = new HttpHeaders();
297	        Pet pet = petMapper.toPet(petFieldsDto);
298	        owner.setId(ownerId);
299	        pet.setOwner(owner);
300	        pet.getType().setName(null);
301	        this.clinicService.savePet(pet);
302	        PetDto petDto = petMapper.toPetDto(pet);
303	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
304	            .buildAndExpand(pet.getId()).toUri());
305	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
311	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
312	        if (currentOwner != null) {
313	            Pet currentPet = this.clinicService.findPetById(petId);
314	            if (currentPet != null) {
315	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
316	                currentPet.setName(petFieldsDto.getName());
317	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
318	                this.clinicService.savePet(currentPet);
319	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
320	            }
321	        }
322	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	    }
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
328	        HttpHeaders headers = new HttpHeaders();
329	        Visit visit = visitMapper.toVisit(visitFieldsDto);
330	        Pet pet = new Pet();
331	        pet.setId(petId);
332	        visit.setPet(pet);
333	        this.clinicService.saveVisit(visit);
334	        VisitDto visitDto = visitMapper.toVisitDto(visit);
335	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
336	            .buildAndExpand(visit.getId()).toUri());
337	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
338	    }
339	
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Override
343	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
344	        Owner owner = this.clinicService.findOwnerById(ownerId);
345	        if (owner != null) {
346	            Pet pet = owner.getPet(petId);
347	            if (pet != null) {
348	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
349	            }
350	        }
351	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	    }
353	}
